const items = $input.all().map((item) => item.json).filter((r) => r && r.recallNumber);

const domainCounts = {};
for (const rec of items) {
  const d = rec.domain || 'unknown';
  domainCounts[d] = (domainCounts[d] || 0) + 1;
}

const lines = items.slice(0, 10).map((rec, idx) => {
  const product = String(rec.productDescription || '').slice(0, 110);
  const dist = String(rec.distributionPattern || 'N/A').slice(0, 80);
  return `${idx + 1}. [${(rec.domain || '').toUpperCase()} | ${rec.riskLevel || 'CRITICAL'}] ${rec.recallingFirm} (${rec.recallNumber})\n   Product: ${product}\n   Distribution: ${dist}\n   FDA Link: ${rec.openFdaPortalUrl || 'https://www.fda.gov/safety/recalls-market-withdrawals-safety-alerts'}`;
});

const summaryHeader = `Weekly FDA Class I Recall Radar — ${items.length} active recall(s) found`;
const breakdownText = Object.entries(domainCounts).map(([k, v]) => `${k}: ${v}`).join(' | ') || 'none';
const digestMarkdown = `${summaryHeader}\nDomains: ${breakdownText}\n\n${lines.join('\n\n')}`;

return [
  {
    json: {
      hasRecalls: items.length > 0,
      totalRecalls: items.length,
      domainCounts,
      digestMarkdown,
      topRecalls: items.slice(0, 10),
    },
  },
];
